// Bug real achado testando com o Edgar (2026-09-06): a Claude manda um bloco "thinking"
// (raciocínio interno) ANTES do bloco de texto de verdade -- pegar sempre content[0] pegava o
// pensamento, não a resposta. Aqui procura pelo bloco cujo "type" é "text", não importa a posição.
const resposta = $input.first().json;
const blocoTexto = (resposta.content || []).find((b) => b.type === 'text');
let texto = blocoTexto?.text ?? '';

// Se vier com ```json ... ``` em volta (acontece às vezes, mesmo pedindo pra não vir), tira as
// crases antes de tentar ler como JSON.
texto = texto.trim().replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();

let dados;
try {
  dados = JSON.parse(texto);
} catch (erro) {
  // Não travar o Mapa por causa de um JSON mal formado -- devolve vazio, o Mapa mostra
  // "webhook respondeu, mas sem os parágrafos esperados" e o corretor tenta de novo.
  dados = { cliente: [], interna: [] };
}

return [{
  json: {
    cliente: Array.isArray(dados.cliente) ? dados.cliente : [],
    interna: Array.isArray(dados.interna) ? dados.interna : [],
  },
}];
